		RequestId:  requestID,
		TraceId:    traceID,
		StatusCode: &statusCode,
		Success:    &successful,
		DurationMs: &durationMs,
		UserAgent:  truncateRunes(c.Request.UserAgent(), 1024),
		Metadata:   metadata,
		OccurredAt: &startedAt,
	}
	if statusCode >= http.StatusBadRequest {
