358:func menuPath(m menuItem) (path string, iframeSrc string) {
359:	uri := normalizeMenuURI(m.URI)
360:	if uri == "" || uri == "#" {
361:		return "/goadmin/menu-" + strconv.FormatInt(m.ID, 10), ""
362:	}
363:
364:	if isExternalHTTPURL(uri) {
365:		return "/goadmin/external-" + strconv.FormatInt(m.ID, 10), uri
366:	}
367:
368:	return "/goadmin" + strings.TrimSuffix(uri, "/"), "/admin" + uri
369:}
