371:func vbenMenuBinding(uri string) (menuRouteBinding, bool) {
372:	binding, ok := vbenMenuRouteBindings[normalizeMenuURI(uri)]
373:	return binding, ok
374:}
375:
376:func normalizeMenuURI(uri string) string {
377:	uri = strings.TrimSpace(uri)
378:	if uri == "" || uri == "#" {
379:		return uri
380:	}
381:	if isExternalHTTPURL(uri) {
382:		return uri
383:	}
384:	if !strings.HasPrefix(uri, "/") {
385:		uri = "/" + uri
386:	}
387:	if uri != "/" {
388:		uri = strings.TrimSuffix(uri, "/")
389:	}
390:	return uri
391:}
392:
393:func normalizeMenuIcon(icon string) string {
394:	icon = strings.TrimSpace(icon)
395:	if icon == "" || strings.Contains(icon, ":") {
396:		return icon
397:	}
398:
399:	switch icon {
400:	case "fa-bar-chart", "fa-dashboard":
401:		return "lucide:layout-dashboard"
402:	case "fa-tasks":
403:		return "lucide:settings-2"
404:	case "fa-users":
405:		return "lucide:users"
406:	case "fa-user":
407:		return "lucide:user"
408:	case "fa-ban":
409:		return "lucide:ban"
410:	case "fa-bars":
411:		return "lucide:menu"
412:	case "fa-history":
413:		return "lucide:history"
414:	default:
415:		return icon
416:	}
417:}
