		Component: "/dashboard/analytics/index",
		Icon:      "lucide:area-chart",
		Meta: map[string]interface{}{
			"affixTab": true,
		},
	},
	"/dashboard/workspace": {
		Name:      "Workspace",
		Path:      "/dashboard/workspace",
		Component: "/dashboard/workspace/index",
		Icon:      "carbon:workspace",
	},
	"/kadmin": {
		Name: "KAdmin",
		Path: "/kadmin",
		Icon: "lucide:settings-2",
	},
	"/kadmin/users": {
		Name:      "KAdminUsers",
