		Icon:      "lucide:users",
	},
	"/kadmin/rbac": {
		Name:      "KAdminRbac",
		Path:      "/kadmin/rbac",
		Component: "/kadmin/components/RbacWorkbench",
		Icon:      "lucide:shield-check",
	},
