	assertOrder("dashboard child", tree[0].Children, []int64{22, 21}, []int64{0, 1})
	assertOrder("kadmin child", tree[1].Children, []int64{12, 13, 11}, []int64{0, 1, 2})
	if tree[0].Children[1].Meta["affixTab"] != true {
