+		t.Fatalf("captured %d arguments, want 3", len(connection.args))
+	}
+}
+
+func TestUpdateNextRunCastsTimestampParameter(t *testing.T) {
+	connection := &captureExecConnection{}
+	repository := &repository{conn: connection}
