		return menu
	}
	if hasBinding {
		menu.Component = binding.Component
		return menu
	}
	if m.Type == menuTypeExternal {
		return menu
	}

	if iframeSrc != "" {
		menu.Component = "IFrameView"
	}
	return menu
}

