func buildManagedMenuTree(items []managedMenu, parentID int64) []managedMenu {
	res := make([]managedMenu, 0)
	for _, item := range items {
		if item.ParentID != parentID {
			continue
		}
		item.Children = buildManagedMenuTree(items, item.ID)
		res = append(res, item)
	}
	return res
}

