func (s *Store) loadAllowedMenuIDsForRoles(roleIDs []interface{}) (map[int64]bool, error) {
	allowed := make(map[int64]bool)
	if len(roleIDs) == 0 {
		return allowed, nil
	}
	rows, err := db.WithDriver(s.conn).
		Table("goadmin_role_menu").
		WhereIn("role_id", roleIDs).
		Select("menu_id").
