func normalizeMenuURI(uri string) string {
	uri = strings.TrimSpace(uri)
	if uri == "" || uri == "#" {
		return uri
	}
	if isExternalHTTPURL(uri) {
		return uri
	}
	if !strings.HasPrefix(uri, "/") {
		uri = "/" + uri
	}
	if uri != "/" {
		uri = strings.TrimSuffix(uri, "/")
	}
	return uri
}

func normalizeMenuIcon(icon string) string {
	icon = strings.TrimSpace(icon)
	if icon == "" || strings.Contains(icon, ":") {
		return icon
	}

	switch icon {
	case "fa-bar-chart", "fa-dashboard":
		return "lucide:layout-dashboard"
	case "fa-tasks":
		return "lucide:settings-2"
	case "fa-users":
		return "lucide:users"
	case "fa-user":
		return "lucide:user"
	case "fa-ban":
		return "lucide:ban"
	case "fa-bars":
		return "lucide:menu"
	case "fa-history":
		return "lucide:history"
	default:
		return icon
	}
}

