import { request } from './client';

export const ADMIN_MENU_TYPE = {
  DIRECTORY: 0,
  MENU: 1,
  EXTERNAL: 2,
} as const;

export type AdminMenuType =
  (typeof ADMIN_MENU_TYPE)[keyof typeof ADMIN_MENU_TYPE];

export interface AdminMenu {
  id: number;
  parentId: number;
  type: AdminMenuType;
  order: number;
  title: string;
  icon: string;
  uri: string;
  component?: string;
  header?: string;
  pluginName?: string;
  uuid?: string;
  createdAt?: string;
  updatedAt?: string;
  children?: AdminMenu[];
}

export interface AdminMenuPayload {
  parentId?: number;
  type?: AdminMenuType;
  order?: number;
  title: string;
  icon?: string;
  uri?: string;
  component?: string;
  header?: string;
  pluginName?: string;
  uuid?: string;
}

