		component = *req.Component
	}
	if *req.Type != menuTypeItem {
		component = ""
	}
	if err := validateMenuComponent(*req.Type, component); err != nil {
		fail(c, http.StatusBadRequest, err.Error())
		return
	}

	_, err = db.WithDriver(s.conn).
