		t.Fatalf("expected leaf type %d, got %d", menuTypeItem, got)
	}
	if got := menuSeedType(directory); got != menuTypeDirectory {
		t.Fatalf("expected directory type %d, got %d", menuTypeDirectory, got)
	}
}

