	ID        int64
	ParentID  int64
	Type      int64
	Order     int64
	Title     string
	Icon      string
	URI       string
	Component string
}

type vbenMenu struct {
	ID        int64                  `json:"id,omitempty"`
	ParentID  int64                  `json:"parentId,omitempty"`
	Name      string                 `json:"name"`
	Path      string                 `json:"path"`
	Component string                 `json:"component,omitempty"`
