		fail(c, http.StatusInternalServerError, err.Error())
		return
	}
	if validationMessage != "" {
		fail(c, http.StatusBadRequest, validationMessage)
		return
	}
	if req.ParentID != 0 {
		descendant, err := s.isMenuDescendant(req.ParentID, menuID)
		if err != nil {
			fail(c, http.StatusInternalServerError, err.Error())
			return
		}
		if descendant {
			fail(c, http.StatusBadRequest, "parent menu cannot be a descendant")
			return
		}
	}
	component := existingMenu.Component
	if req.Component != nil {
		component = *req.Component
	}
	if *req.Type != menuTypeItem {
		component = ""
	}
	if err := validateMenuComponent(*req.Type, component); err != nil {
		fail(c, http.StatusBadRequest, err.Error())
		return
	}

	_, err = db.WithDriver(s.conn).
		Table("goadmin_menu").
		Where("id", "=", menuID).
		Update(dialect.H{
			"parent_id":   req.ParentID,
			"type":        *req.Type,
			"order":       req.Order,
			"title":       req.Title,
			"icon":        req.Icon,
			"uri":         req.URI,
			"header":      req.Header,
			"plugin_name": req.PluginName,
			"uuid":        req.UUID,
			"component":   component,
			"updated_at":  nowString(),
		})
	if err != nil {
		fail(c, http.StatusInternalServerError, err.Error())
		return
	}

	menu, err := s.loadManagedMenu(menuID)
	if err != nil {
		fail(c, http.StatusInternalServerError, err.Error())
		return
	}
	success(c, menu)
}

